protocol PriceServiceProtocol { func price(_ sku: String) throws -> Money }

struct FakePrices: PriceServiceProtocol {          // stands in for the remote
    let canned: [String: Money]
    func price(_ sku: String) throws -> Money {
        guard let money = canned[sku] else { throw ServiceError.unknownSku(sku) }
        return money
    }
}

let checkout = Checkout(prices: FakePrices(canned: ["A-1": Money(cents: 999)]))

